import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"MSR(Mutli-Step Retry)- An Generalization of CRUSH Allowing Multiple OSDs Per Failure Domain- S. Just","description":"","frontmatter":{"title":"MSR(Mutli-Step Retry)- An Generalization of CRUSH Allowing Multiple OSDs Per Failure Domain- S. Just","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","CRUSH算法","MSR规则","分布式存储","数据分布"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/MSR_Mutli-Step_Retry_-_An_Generalization_of_CRUSH_Allowing_Multiple_OSDs_Per_Failure_Domain-_S._Just.md","filePath":"posts/2025/MSR_Mutli-Step_Retry_-_An_Generalization_of_CRUSH_Allowing_Multiple_OSDs_Per_Failure_Domain-_S._Just.md","lastUpdated":1780459816000}'),l={name:"posts/2025/MSR_Mutli-Step_Retry_-_An_Generalization_of_CRUSH_Allowing_Multiple_OSDs_Per_Failure_Domain-_S._Just.md"};function i(n,t,s,_,h,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h3 id="ceph-msr规则讨论会议纪要" tabindex="-1"><strong>Ceph MSR规则讨论会议纪要</strong> <a class="header-anchor" href="#ceph-msr规则讨论会议纪要" aria-label="Permalink to &quot;**Ceph MSR规则讨论会议纪要**&quot;">​</a></h3><h4 id="会议概述" tabindex="-1"><strong>会议概述</strong> <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;**会议概述**&quot;">​</a></h4><p>本次会议主要讨论了Ceph分布式存储系统中CRUSH算法的改进版本——MSR（Multi-Step Retry）规则。该规则旨在解决传统CRUSH在处理密集EC（Erasure Coding）集群时的局限性，并提高了Ceph在密集EC场景下的性能和稳定性。</p><h4 id="关键议题与讨论内容" tabindex="-1"><strong>关键议题与讨论内容</strong> <a class="header-anchor" href="#关键议题与讨论内容" aria-label="Permalink to &quot;**关键议题与讨论内容**&quot;">​</a></h4><h5 id="_1-crush算法回顾" tabindex="-1"><strong>1. CRUSH算法回顾</strong> <a class="header-anchor" href="#_1-crush算法回顾" aria-label="Permalink to &quot;**1. CRUSH算法回顾**&quot;">​</a></h5><ul><li><strong>核心功能</strong>：CRUSH是Ceph用于数据分布的确定性算法，通过哈希对象名生成PG（Placement Group）ID，再结合OSD Map映射到具体的OSD。</li><li><strong>关键特性</strong>：稳定性、容灾与权重感知、层级选择。</li></ul><h5 id="_2-传统crush的局限性" tabindex="-1"><strong>2. 传统CRUSH的局限性</strong> <a class="header-anchor" href="#_2-传统crush的局限性" aria-label="Permalink to &quot;**2. 传统CRUSH的局限性**&quot;">​</a></h5><ul><li><strong>密集EC集群问题</strong>：在小型集群中，难以均匀分布EC分片，导致容灾能力下降。</li><li><strong>Chooseleaf的不足</strong>：在多步骤选择时，若中间步骤故障，可能被迫在同一Host内重试。</li></ul><h5 id="_3-msr规则的设计与优势" tabindex="-1"><strong>3. MSR规则的设计与优势</strong> <a class="header-anchor" href="#_3-msr规则的设计与优势" aria-label="Permalink to &quot;**3. MSR规则的设计与优势**&quot;">​</a></h5><ul><li><strong>核心改进</strong>：深度优先+多向量管理、动态重试逻辑。</li><li><strong>用例适配</strong>：适用于小规模EC集群，如跨少量Host分布宽条带编码。</li></ul><h5 id="_4-实现细节与调优" tabindex="-1"><strong>4. 实现细节与调优</strong> <a class="header-anchor" href="#_4-实现细节与调优" aria-label="Permalink to &quot;**4. 实现细节与调优**&quot;">​</a></h5><ul><li><strong>参数调优</strong>：<code>retry_collision</code>、<code>max_retries</code>。</li><li><strong>稳定性保障</strong>：严格测试映射一致性。</li></ul><h5 id="_5-决策与行动计划" tabindex="-1"><strong>5. 决策与行动计划</strong> <a class="header-anchor" href="#_5-决策与行动计划" aria-label="Permalink to &quot;**5. 决策与行动计划**&quot;">​</a></h5><ul><li><strong>推广MSR规则</strong>：在EC池配置中优先使用<code>osd_per_failure_domain</code>参数，自动化生成MSR规则。</li><li><strong>兼容性维护</strong>：确保MSR与传统CRUSH规则共存。</li><li><strong>性能监控</strong>：收集用户反馈，验证MSR在小集群中的实际效果。</li></ul><h5 id="_6-遗留问题与后续跟进" tabindex="-1"><strong>6. 遗留问题与后续跟进</strong> <a class="header-anchor" href="#_6-遗留问题与后续跟进" aria-label="Permalink to &quot;**6. 遗留问题与后续跟进**&quot;">​</a></h5><ul><li><strong>用户适配</strong>：评估迁移至MSR的必要性。</li><li><strong>高级调优</strong>：补充用例指南，针对极端场景调整参数。</li></ul><h4 id="会议记录人-ceph社区研发团队" tabindex="-1"><strong>会议记录人</strong>：Ceph社区研发团队 <a class="header-anchor" href="#会议记录人-ceph社区研发团队" aria-label="Permalink to &quot;**会议记录人**：Ceph社区研发团队&quot;">​</a></h4><h4 id="日期-2023年x月x日" tabindex="-1"><strong>日期</strong>：2023年X月X日 <a class="header-anchor" href="#日期-2023年x月x日" aria-label="Permalink to &quot;**日期**：2023年X月X日&quot;">​</a></h4>',18)])])}const S=e(l,[["render",i]]);export{g as __pageData,S as default};
